mapper.select:
SELECT l.id, l.project_id AS projectId, l.project_name AS projectName, l.action_type AS actionType, l.from_engineer_id AS fromEngineerId, l.from_engineer_name AS fromEngineerName, l.to_engineer_id AS toEngineerId, l.to_engineer_name AS toEngineerName, l.operated_by AS operatedBy, l.operator_name AS operatorName, l.operated_at AS operatedAt, l.remark FROM biz_project_transfer_log l
AND l.project_id = #{query.projectId}
AND l.operated_by = #{query.operatedBy}
AND l.action_type = #{query.actionType}
AND l.operated_at >= CONCAT(#{query.dateBegin}, ' 00:00:00')
AND l.operated_at <= CONCAT(#{query.dateEnd}, ' 23:59:59')
ORDER BY l.operated_at DESC, l.id DESC
